// Health Watchdog — детект триггеров (Фаза 4b). Run Once for All Items.
// Триггеры: (1) новая сдача крови → нужен разбор; (2) маркер вне референса → нудж;
// (3) резкое ухудшение симптома → нудж. Ниже 1 открытого расследования — нуджи не шлём.
function safeAll(n) { try { return $(n).all().map(i => i.json); } catch (e) { return []; } }
function num(v) { if (v == null || v === '') return null; const x = parseFloat(String(v).replace(',', '.').replace(/\s/g, '')); return isNaN(x) ? null : x; }
function d10(v) {
  let s = String(v == null ? '' : v).trim();
  let m = s.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{4})/); if (m) return m[3] + '-' + m[2].padStart(2, '0') + '-' + m[1].padStart(2, '0');
  m = s.match(/^(\d{4})[.\/-](\d{1,2})[.\/-](\d{1,2})/); if (m) return m[1] + '-' + m[2].padStart(2, '0') + '-' + m[3].padStart(2, '0');
  return s.slice(0, 10);
}
const DAY = 86400000;
const today = new Date(Date.now() + 10 * 3600 * 1000).toISOString().slice(0, 10);
const dAgo = d => new Date(Date.now() + 10 * 3600 * 1000 - d * DAY).toISOString().slice(0, 10);

const results = safeAll('Get Results');
const markers = safeAll('Get Markers');
const visits  = safeAll('Get Visits');
const symRows = safeAll('Get Symptom_Log');
const invRows = safeAll('Get Investigations');
const daySum  = safeAll('Get day_sum');
const daily   = safeAll('Get Daily_Trends');
const medsRows = safeAll('Get Meds');

const sd = $getWorkflowStaticData('global');
sd.nudged = sd.nudged || {};

const markName = {}; markers.forEach(m => { if (m.Marker_ID) markName[m.Marker_ID] = m.Name; });
const vSorted = visits.filter(v => v.Date && v.Visit_ID).sort((a, b) => d10(a.Date).localeCompare(d10(b.Date)));
const newest = vSorted[vSorted.length - 1] || null;
const prev   = vSorted[vSorted.length - 2] || null;
const newestDate = newest ? d10(newest.Date) : null;

function visitMarkers(vid) {
  const o = {};
  results.filter(r => r.Visit_ID === vid).forEach(r => {
    const val = num(r.Value); if (val == null) return;
    o[markName[r.Marker_ID] || r.Marker_ID] = { value: val, lo: num(r.Lab_Min), hi: num(r.Lab_Max), unit: r.Original_Unit || '' };
  });
  return o;
}
const newestM = newest ? visitMarkers(newest.Visit_ID) : {};
const prevM   = prev ? visitMarkers(prev.Visit_ID) : {};

// --- (1) новая сдача ---
const visitAgeDays = newestDate ? (Date.now() - new Date(newestDate + 'T12:00:00+10:00').getTime()) / DAY : 9999;
const alreadyReviewed = sd.lastReviewedVisit === (newest && newest.Visit_ID);
const recentEnough = visitAgeDays < 30;
const needs_lab_review = !!(newest && !alreadyReviewed && recentEnough && Object.keys(newestM).length >= 2);

// --- хронические маркеры (конституция) из Patient_State — про них не нудить ---
const pstateRows = safeAll('Get Patient_State');
const chronicRx = pstateRows
  .map(x => String(x.Contra_Other || '') + ' ' + String(x.Note || ''))
  .join(' ').toLowerCase();
function isChronicMarker(name) {
  const n = name.toLowerCase();
  // явно хронически низкие лейкоциты
  if (/лейкоцит|wbc/.test(n) && /лейкоцит|конституц|хроническ.*низк/.test(chronicRx)) return true;
  return false;
}

// --- (2) маркеры вне референса — ТОЛЬКО из свежей сдачи (≤45 дн). Ключ дедупа с Visit_ID (Opus 5). ---
const abnormal = [];
if (visitAgeDays <= 45 && newest) {
  for (const [name, m] of Object.entries(newestM)) {
    if (isChronicMarker(name)) continue;
    const base = { key: 'm:' + newest.Visit_ID + ':' + name, name, value: m.value };
    if (m.lo != null && m.value < m.lo) abnormal.push({ ...base, ref: m.lo + '–' + (m.hi ?? '?'), flag: 'ниже нормы' });
    else if (m.hi != null && m.value > m.hi) abnormal.push({ ...base, ref: (m.lo ?? '?') + '–' + m.hi, flag: 'выше нормы' });
    // (2b) маркер ЗАМЕТНО ухудшился vs прошлая сдача, оставаясь в норме
    else if (prevM[name] != null && prevM[name].value != null) {
      const pv = prevM[name].value;
      if (pv !== 0 && Math.abs(m.value - pv) / Math.abs(pv) >= 0.18) {
        // ухудшение — движение к ближней границе референса
        const towardHi = m.hi != null && (m.value - pv) > 0 && (m.hi - m.value) < (m.hi - pv);
        const towardLo = m.lo != null && (m.value - pv) < 0 && (m.value - m.lo) < (pv - m.lo);
        if (towardHi || towardLo) abnormal.push({ ...base, ref: (m.lo ?? '?') + '–' + (m.hi ?? '?'),
          flag: 'сдвиг ' + pv + ' → ' + m.value + ' (в норме, но к границе)' });
      }
    }
  }
}

// --- (2c) просроченный Lab_Plan ---
const labPlan = safeAll('Get Lab_Plan');
const overdueLab = labPlan
  .filter(r => r.Test && !['done', 'paused', 'archived'].includes(String(r.Status || 'active').toLowerCase()))
  .map(r => ({ test: r.Test, due: d10(r.Next_Due) }))
  .filter(r => r.due && r.due.length === 10 && (new Date(today) - new Date(r.due)) / DAY >= 14)
  .map(r => ({ key: 'lp:' + r.test + ':' + r.due, ...r,
    overdue_days: Math.round((new Date(today) - new Date(r.due)) / DAY) }));

// --- (3) резкое ухудшение симптома за 3 дня ---
const symAlerts = symRows
  .filter(s => s.Symptom && String(s.Symptom_ID || '').toLowerCase() !== 'demo-format' && d10(s.Date) >= dAgo(3))
  .filter(s => num(s.Severity) >= 4 || /усил|верн|появ/i.test(String(s.Change || '')))
  .map(s => ({ key: 's:' + s.Symptom_ID + ':' + d10(s.Date), symptom: s.Symptom, severity: num(s.Severity), change: s.Change || '', id: s.Symptom_ID }));

// --- открытое расследование? (TTL 30 дней — Opus 5: забытая строка не должна глушить проактив навсегда) ---
const openInvRows = invRows.filter(v => v.Inv_ID && String(v.Inv_ID).toLowerCase() !== 'demo-format'
