  parts.push(d.new_overdue.map(a=>a.test+' — просрочен на '+a.overdue_days+' дн (был на '+a.due+')').join('; '));
}
if (d.new_sym_alerts && d.new_sym_alerts.length) {
  parts.push('\n=== СИМПТОМ УСИЛИЛСЯ (блок «⚠️ По симптому:») ===');
  parts.push(d.new_sym_alerts.map(a=>a.symptom+' (тяжесть '+a.severity+', '+a.change+')').join('; '));
}
if ((d.new_abnormal&&d.new_abnormal.length) || (d.new_sym_alerts&&d.new_sym_alerts.length) || (d.new_overdue&&d.new_overdue.length)) {
  parts.push('\nВ конце блоков про отклонения/симптомы/анализы добавь: «Если хочешь — напиши мне, разберём спокойно, нужно ли к врачу.»');
}
