  parts.push('Сегодня не удалось прочитать: ' + d.read_failures.join(', ') + ' (вероятно лимит Google Sheets). Проверка симптомов и анализов по этим листам НЕ проведена.');
  parts.push('Скажи пациенту коротко и без тревоги: «Сегодня часть данных не прочиталась — проверю завтра. Если у тебя недавно была сдача крови или появился/усилился симптом — напиши мне, разберём.»');
}
if (d.stale_investigations && d.stale_investigations.length) {
