(d.new_overdue||[]).forEach(a => { sd.nudged[a.key] = today; });
return [{ json: { save_note: d.needs_lab_review, note_date: today,
  note_text: d.needs_lab_review ? ('Автоматический разбор свежей сдачи (' + (d.newest_visit&&d.newest_visit.date) + '). ' + llm.replace(/<[^>]+>/g,'')).slice(0,1500) : '' } }];

