    else if (m.hi != null && m.value > m.hi) abnormal.push({ ...base, ref: (m.lo ?? '?') + '–' + m.hi, flag: 'выше нормы' });
    // (2b) маркер ЗАМЕТНО ухудшился vs прошлая сдача, оставаясь в норме
    else if (prevM[name] != null && prevM[name].value != null) {
      const pv = prevM[name].value;
      if (pv !== 0 && Math.abs(m.value - pv) / Math.abs(pv) >= 0.18) {
        // ухудшение — движение к ближней границе референса
        const towardHi = m.hi != null && (m.value - pv) > 0 && (m.hi - m.value) < (m.hi - pv);
        const towardLo = m.lo != null && (m.value - pv) < 0 && (m.value - m.lo) < (pv - m.lo);
        if (towardHi || towardLo) abnormal.push({ ...base, ref: (m.lo ?? '?') + '–' + (m.hi ?? '?'),
          flag: 'сдвиг ' + pv + ' → ' + m.value + ' (в норме, но к границе)' });
      }
    }
  }
}

// --- (2c) просроченный Lab_Plan ---
const labPlan = safeAll('Get Lab_Plan');
const overdueLab = labPlan
  .filter(r => r.Test && !['done', 'paused', 'archived'].includes(String(r.Status || 'active').toLowerCase()))
  .map(r => ({ test: r.Test, due: d10(r.Next_Due) }))
  .filter(r => r.due && r.due.length === 10 && (new Date(today) - new Date(r.due)) / DAY >= 14)
  .map(r => ({ key: 'lp:' + r.test + ':' + r.due, ...r,
    overdue_days: Math.round((new Date(today) - new Date(r.due)) / DAY) }));

// --- (3) резкое ухудшение симптома за 3 дня ---
const symAlerts = symRows
  .filter(s => s.Symptom && String(s.Symptom_ID || '').toLowerCase() !== 'demo-format' && d10(s.Date) >= dAgo(3))
  .filter(s => num(s.Severity) >= 4 || /усил|верн|появ/i.test(String(s.Change || '')))
  .map(s => ({ key: 's:' + s.Symptom_ID + ':' + d10(s.Date), symptom: s.Symptom, severity: num(s.Severity), change: s.Change || '', id: s.Symptom_ID }));

// --- открытое расследование? (TTL 30 дней — Opus 5: забытая строка не должна глушить проактив навсегда) ---
const openInvRows = invRows.filter(v => v.Inv_ID && String(v.Inv_ID).toLowerCase() !== 'demo-format'
  && String(v.Status || '').toLowerCase() === 'open');
const activeInv = openInvRows.filter(v => {
  const upd = d10(v.Updated || v.Opened);
  return !upd || (new Date(today) - new Date(upd)) / DAY < 30;
});
const open_investigation = activeInv.length > 0;
const stale_investigations = openInvRows.filter(v => !activeInv.includes(v)).map(v => v.Inv_ID);

// --- нуджи только про новое ---
const new_abnormal   = abnormal.filter(a => !sd.nudged[a.key]);
const new_sym_alerts = symAlerts.filter(a => !sd.nudged[a.key]);
const new_overdue    = overdueLab.filter(a => !sd.nudged[a.key]);
const should_nudge = !open_investigation && (new_abnormal.length > 0 || new_sym_alerts.length > 0 || new_overdue.length > 0);

// --- контекст периода для разбора анализов ---
const periodFrom = prev ? d10(prev.Date) : dAgo(120);
function periodRows(rows, dateKey) { return rows.filter(r => { const d = d10(r[dateKey] || r.Date || r['Дата']); return d >= periodFrom && d <= (newestDate || today); }); }
function avgOf(rows, key) { const v = rows.map(r => num(r[key])).filter(x => x != null); return v.length ? Math.round(v.reduce((s, x) => s + x, 0) / v.length * 10) / 10 : null; }
const ds = periodRows(daySum, 'Date');
const dt = periodRows(daily, 'Дата');
const nutrition_period = {
  days: ds.length,
  avg_added_sugar_g: avgOf(ds, 'Добавленный сахар') ?? avgOf(ds, 'Добавленный_сахар'),
  avg_sat_fat_g: avgOf(ds, 'Насыщенные жиры') ?? avgOf(ds, 'Насыщенные_жиры'),
  avg_fiber_g: avgOf(ds, 'Клетчатка'),
  avg_kcal: avgOf(ds, 'Калории') ?? avgOf(ds, 'Всего_ккал'),
};
const wellness_period = {
  days: dt.length,
  avg_hrv: avgOf(dt, 'ВСР_ночная'),
  avg_rhr: avgOf(dt, 'Пульс_ночной_средний'),
  avg_sleep_min: avgOf(dt, 'Чистый_сон_мин'),
  avg_training_kcal: avgOf(dt, 'Тренировка_Ккал'),
  meds_seen: [...new Set(dt.map(r => String(r['Лекарства_принимаемые'] || '')).filter(Boolean).join('\n').split('\n').map(x => x.trim()).filter(Boolean))].slice(0, 12),
};

// --- картотека препаратов (лист Meds) для разбора анализов ---
const medsCard = medsRows
  .filter(m => m && (m.Name || m.Med_ID) && String(m.Med_ID || '').toLowerCase() !== 'demo-format')
  .map(m => {
    const st = d10(m.Started), sp = d10(m.Stopped);
    return {
      name: String(m.Name || m.Med_ID).trim(),
      class: String(m.Class || '').trim() || null,
      dose: String(m.Dose || '').trim() || null,
      status: String(m.Status || '').trim().toLowerCase() || 'unknown',
      started: /^\d{4}-\d{2}-\d{2}$/.test(st) ? st : null,
      stopped: /^\d{4}-\d{2}-\d{2}$/.test(sp) ? sp : null,
      reason: String(m.Reason || '').trim() || null,
    };
  });
const meds_active = medsCard.filter(m => ['active', 'prn', 'paused'].includes(m.status));
const meds_changed_near_visit = newestDate ? medsCard
  .filter(m => {
    const evt = m.stopped || m.started;
    return evt && Math.abs(new Date(newestDate) - new Date(evt)) / DAY <= 45;
  })
  .map(m => ({ ...m, event: m.stopped ? ('курс завершён ' + m.stopped) : ('курс начат ' + m.started) })) : [];
const medications = { active: meds_active, changed_near_visit: meds_changed_near_visit };

// --- A4 (ревью Opus 5): различить «прочитал, пусто» и «не смог прочитать» ---
// Эти листы НИКОГДА не бывают легитимно пустыми: Daily_Trends (Garmin пишет ежедневно),
// Visits/Results (14 лет истории), Patient_State (засижен строкой про грыжу),
// Symptom_Log (есть demo-format + бэкфилл). 0 строк = сбой чтения (rate-limit), а не «сигналов нет».
const read_failures = [];
if (daily.length === 0)      read_failures.push('Daily_Trends');
if (visits.length === 0)     read_failures.push('Visits');
if (results.length === 0)    read_failures.push('Results');
if (pstateRows.length === 0) read_failures.push('Patient_State');
if (symRows.length === 0)    read_failures.push('Symptom_Log');
// нудж о сбое чтения — не чаще раза в 3 дня (чтобы не спамить при хронически тесной квоте)
const lastRF = sd.lastReadFailNotice ? (new Date(today) - new Date(sd.lastReadFailNotice)) / DAY : 999;
const notify_read_failure = read_failures.length > 0 && lastRF >= 3;
if (notify_read_failure) sd.lastReadFailNotice = today;

return [{
  json: {
    fire: needs_lab_review || should_nudge || notify_read_failure,
    needs_lab_review, should_nudge, open_investigation,
    read_failures, notify_read_failure,
    newest_visit: newest ? { id: newest.Visit_ID, date: newestDate } : null,
    newest_markers: newestM, prev_visit_date: prev ? d10(prev.Date) : null, prev_markers: prevM,
    abnormal, new_abnormal, new_sym_alerts, new_overdue,
    stale_investigations,
    period: { from: periodFrom, to: newestDate || today },
    nutrition_period, wellness_period, medications,
    today,
  },
}];

