}
if (d.notify_read_failure && d.read_failures && d.read_failures.length) {
  parts.push('\n=== НЕ ПРОЧИТАНЫ ЛИСТЫ (блок «⚠️ Данные:») ===');
  parts.push('Сегодня не удалось прочитать: ' + d.read_failures.join(', ') + ' (вероятно лимит Google Sheets). Проверка симптомов и анализов по этим листам НЕ проведена.');
  parts.push('Скажи пациенту коротко и без тревоги: «Сегодня часть данных не прочиталась — проверю завтра. Если у тебя недавно была сдача крови или появился/усилился симптом — напиши мне, разберём.»');
}
if (d.stale_investigations && d.stale_investigations.length) {
  parts.push('\n(служебное, покажи мелким шрифтом в самом конце: расследования без обновления >30 дн — ' + d.stale_investigations.join(', ') + ' — считаю приостановленными.)');
}
parts.push('\nФормат: готовый текст для Telegram, ≤1400 знаков, теги <b> <i> допустимы, без Markdown. Начни с «🩺 <b>Разбор от системы</b>» если есть разбор анализов, иначе сразу с первого блока.');
return [{ json: { prompt: parts.join('\n') } }];

